enum NotificationUrgency { low, normal, high }
class NotificationCandidate { const NotificationCandidate({required this.id,required this.title,required this.urgency,required this.createdAt,this.read=false}); final String id,title; final NotificationUrgency urgency; final DateTime createdAt; final bool read; }
class NotificationDigest { const NotificationDigest(this.immediate,this.digest); final List<NotificationCandidate> immediate,digest; }
class NotificationDigestPlanner { const NotificationDigestPlanner(); NotificationDigest plan(Iterable<NotificationCandidate> items,{required DateTime now,Duration maxAge=const Duration(days:7)}){if(maxAge.isNegative)throw ArgumentError.value(maxAge);final seen=<String>{};final hot=<NotificationCandidate>[],later=<NotificationCandidate>[];for(final n in items){if(n.id.trim().isEmpty||!seen.add(n.id)||n.read||n.createdAt.isAfter(now)||now.difference(n.createdAt)>maxAge)continue;(n.urgency==NotificationUrgency.high?hot:later).add(n);}hot.sort((a,b)=>b.createdAt.compareTo(a.createdAt));later.sort((a,b){final u=b.urgency.index.compareTo(a.urgency.index);return u!=0?u:b.createdAt.compareTo(a.createdAt);});return NotificationDigest(List.unmodifiable(hot),List.unmodifiable(later));}}
